// 3 years back -> 6 months ahead
const from = new Date(); from.setFullYear(from.getFullYear() - 3);
const to = new Date(); to.setMonth(to.getMonth() + 6);
return [{ json: { startDate: from.toISOString(), endDate: to.toISOString() } }];

// ============================================================
// PATIENTS RECOVERY from Google Calendar
// DRY_RUN = true  -> nothing is written, only a report is shown
// DRY_RUN = false -> new patients are appended, changed phones are updated
// ============================================================
const DRY_RUN = true;

// --- Patient matching helpers (same logic in upsert + recovery) ---
// Strip leading status icons (⏳ ✅ 🔔 ...) and stray punctuation from a name
function cleanName(n) {
  return String(n || '')
    .replace(/^[^\p{L}\p{N}]+/u, '')
    .replace(/\s+/g, ' ')
    .replace(/[\s.,;:\-]+$/, '')
    .trim();
}
function nameKey(n) {
  return cleanName(n).toLowerCase();
}
// Normalize to +359 international format (text-safe for Google Sheets)
function toInternational(p) {
  let phone = String(p || '').replace(/[\s()\-.\/]/g, '');
  if (!phone) return '';
  if (phone.startsWith('00359')) phone = '+359' + phone.slice(5);
  else if (phone.startsWith('359')) phone = '+' + phone;
  else if (phone.startsWith('0') && phone.length >= 10) phone = '+359' + phone.slice(1);
  else if (/^[89]\d{8}$/.test(phone)) phone = '+359' + phone;
  else if (!phone.startsWith('+') && phone.length >= 9) phone = '+359' + phone;
  return phone;
}
// Core digits for comparison: +359887493315 / 0887493315 / 887493315 -> 887493315
function phoneKey(p) {
  return String(p || '').replace(/\D/g, '').replace(/^00/, '').replace(/^359/, '').replace(/^0/, '');
}
function isBlockName(n) {
  return /блокиран|почивка|отпуск|blocked/i.test(String(n || ''));
}

function extractPhone(description) {
  const text = String(description || '').replace(/<[^>]*>/g, ' ');
  const patterns = [
    /📞\s*Тел[.:]?\s*([+\d\s()\-]{7,})/i,
    /(?:тел|phone|tel)[.:\s]+([+\d\s()\-]{7,})/i,
    /((?:\+359|00359)[\d\s]{8,12})/,
    /\b(0[2-9][\d\s]{7,10})\b/
  ];
  for (const re of patterns) {
    const m = text.match(re);
    if (m) {
      const phone = toInternational(m[1]);
      if (/^\+359\d{8,9}$/.test(phone)) return phone;
    }
  }
  return '';
}

// 1) Latest known data per patient name from the calendar (oldest -> newest)
const events = $('Get All Calendar Events').all()
  .map(i => i.json)
  .filter(e => e && e.id && e.start && e.start.dateTime && e.status !== 'cancelled')
  .sort((a, b) => String(a.start.dateTime).localeCompare(String(b.start.dateTime)));

const fromCalendar = new Map();
for (const ev of events) {
  const name = cleanName(ev.summary);
  if (!name || name.length < 2 || isBlockName(name)) continue;
  const key = nameKey(name);
  const phone = extractPhone(ev.description);
  const prev = fromCalendar.get(key) || { name, phone: '', lastDate: '' };
  prev.name = name;
  if (phone) prev.phone = phone;            // newest phone wins
  prev.lastDate = ev.start.dateTime.slice(0, 10);
  fromCalendar.set(key, prev);
}

// 2) Existing sheet rows
const rows = $('Read Existing Patients').all()
  .map(i => i.json)
  .filter(r => r && r.row_number && (r.name || r.phone));
const rowsByName = new Map();
for (const r of rows) {
  const k = nameKey(r.name);
  if (!rowsByName.has(k)) rowsByName.set(k, []);
  rowsByName.get(k).push(r);
}

// 3) Plan
const today = new Date().toISOString().split('T')[0];
const toAdd = [];
const toUpdate = [];
for (const [key, p] of fromCalendar) {
  const existing = rowsByName.get(key) || [];
  if (existing.length === 0) {
    toAdd.push({ op: 'append', name: p.name, phone: p.phone, createdAt: today, lastVisit: p.lastDate });
    continue;
  }
  if (!p.phone) continue;
  if (existing.some(r => phoneKey(r.phone) === phoneKey(p.phone))) continue;
  const noPhoneRow = existing.find(r => !phoneKey(r.phone));
  const target = noPhoneRow || (existing.length === 1 ? existing[0] : null);
  if (target) {
    toUpdate.push({ op: 'update', rowNumber: target.row_number, name: target.name,
                    oldPhone: String(target.phone || ''), phone: p.phone, lastVisit: p.lastDate });
  } else {
    toAdd.push({ op: 'append', name: p.name, phone: p.phone, createdAt: today, lastVisit: p.lastDate });
  }
}

const report = {
  op: 'report',
  dryRun: DRY_RUN,
  summary: `${DRY_RUN ? 'ПРОБА (нищо не е записано)' : 'ЗАПИСАНО'}: ` +
    `събития ${events.length}, пациенти в календара ${fromCalendar.size}, ` +
    `редове в таблицата ${rows.length}, нови ${toAdd.length}, обновени телефони ${toUpdate.length}`,
  toAdd: toAdd.map(p => `${p.name} | ${p.phone || '(без телефон)'} | последен час ${p.lastVisit}`),
  toUpdate: toUpdate.map(p => `ред ${p.rowNumber}: ${p.name} | ${p.oldPhone || '(празно)'} -> ${p.phone}`)
};

if (DRY_RUN) return [{ json: report }];
return [{ json: report }, ...toAdd.map(p => ({ json: p })), ...toUpdate.map(p => ({ json: p }))];
